/* Generated by Mzian.net — progressive enhancements: the site works without JavaScript. */
(function () {
  'use strict';
  var body = document.body;
  var root = body.getAttribute('data-root') || '';
  var currency = body.getAttribute('data-currency') || '';
  var store = body.getAttribute('data-store') || 'mzian-cart';

  function money(value) {
    var n = Number(value || 0);
    return n.toLocaleString(document.documentElement.lang || 'fr', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' ' + currency;
  }
  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text !== undefined && text !== null) node.textContent = String(text); // never innerHTML with remote data
    return node;
  }

  // Mobile navigation
  document.querySelectorAll('[data-toggle]').forEach(function (button) {
    var target = document.getElementById(button.getAttribute('data-toggle'));
    button.addEventListener('click', function () {
      var open = target.classList.toggle('open');
      button.setAttribute('aria-expanded', String(open));
    });
  });

  // Form result messages (?sent=1, ?error=invalid|throttled)
  var params = new URLSearchParams(window.location.search);
  var state = params.get('sent') ? 'sent' : params.get('error');
  if (state) {
    document.querySelectorAll('[data-status="' + state + '"]').forEach(function (n) { n.hidden = false; });
  }

  // Live collections: refresh the generated list from the management application.
  function renderItem(config, row) {
    var card = el('article', 'card item');
    config.fields.forEach(function (field, index) {
      var value = row[field.name];
      if (value === null || value === undefined || value === '') return;
      if (index === 0) { card.appendChild(el('h3', '', value)); return; }
      if (field.type === 'money') {
        var suffix = field.name === 'price_per_day' ? ' ' + config.per_day : (field.name === 'price_per_night' ? ' ' + config.per_night : '');
        card.appendChild(el('p', 'price', money(value) + suffix)); return;
      }
      if (field.type === 'select') { card.appendChild(el('span', 'tag', (field.options || {})[value] || value)); return; }
      if (field.type === 'textarea') { card.appendChild(el('p', 'muted', value)); return; }
      if (field.name === 'duration_minutes') { card.appendChild(el('span', 'tag', value + ' ' + config.minutes)); return; }
      if (field.type === 'number') { card.appendChild(el('span', 'tag', field.label + ' : ' + value)); return; }
      card.appendChild(el('span', 'tag', value));
    });
    if (config.shop) {
      var button = el('button', 'btn small add', config.add);
      button.type = 'button';
      button.setAttribute('data-add', JSON.stringify({ id: row.id, name: row.name, price: row.price }));
      card.appendChild(button);
    }
    return card;
  }
  function feed(entity) {
    return fetch(root + 'admin/index.php?public=feed&entity=' + encodeURIComponent(entity), { headers: { Accept: 'application/json' } })
      .then(function (r) { if (!r.ok) throw new Error('feed'); return r.json(); })
      .then(function (data) { return data.items || []; });
  }
  document.querySelectorAll('[data-feed]').forEach(function (list) {
    var entity = list.getAttribute('data-feed');
    var configNode = document.querySelector('[data-feed-config="' + entity + '"]');
    if (!configNode) return;
    var config = JSON.parse(configNode.textContent);
    var limit = Number(list.getAttribute('data-limit') || 0);
    feed(entity).then(function (items) {
      if (limit > 0) items = items.slice(0, limit);
      list.textContent = '';
      if (!items.length) { list.appendChild(el('p', 'muted', config.empty)); return; }
      items.forEach(function (row) { list.appendChild(renderItem(config, row)); });
      bindCart();
    }).catch(function () { /* static preview: keep the generated content */ });
  });

  // Published reviews
  document.querySelectorAll('[data-review-list]').forEach(function (list) {
    feed('reviews').then(function (items) {
      items.forEach(function (review) {
        var card = el('article', 'card');
        card.appendChild(el('p', 'price', '★★★★★'.slice(0, Number(review.rating) || 5)));
        card.appendChild(el('p', '', review.comment));
        card.appendChild(el('p', 'muted small', review.author));
        list.appendChild(card);
      });
      var section = list.closest('[data-reviews]');
      if (section && items.length) section.hidden = false;
    }).catch(function () {});
  });

  // Cart (shop) — the total is recomputed by the shop owner when confirming the order.
  function readCart() { try { return JSON.parse(localStorage.getItem(store) || '[]'); } catch (e) { return []; } }
  function writeCart(cart) { try { localStorage.setItem(store, JSON.stringify(cart)); } catch (e) {} renderCart(); }
  function bindCart() {
    document.querySelectorAll('[data-add]').forEach(function (button) {
      if (button.getAttribute('data-bound')) return;
      button.setAttribute('data-bound', '1');
      button.addEventListener('click', function () {
        var product = JSON.parse(button.getAttribute('data-add'));
        var cart = readCart();
        var line = cart.filter(function (l) { return l.id === product.id && l.name === product.name; })[0];
        if (line) { line.qty += 1; } else { cart.push({ id: product.id, name: product.name, price: Number(product.price) || 0, qty: 1 }); }
        writeCart(cart);
      });
    });
  }
  function renderCart() {
    var cart = readCart();
    var count = cart.reduce(function (s, l) { return s + l.qty; }, 0);
    var total = cart.reduce(function (s, l) { return s + l.qty * l.price; }, 0);
    document.querySelectorAll('[data-cart-count]').forEach(function (n) { n.textContent = String(count); });
    document.querySelectorAll('[data-cart-total-label]').forEach(function (n) { n.textContent = money(total); });
    document.querySelectorAll('[data-cart-total]').forEach(function (n) { n.value = total.toFixed(2); });
    document.querySelectorAll('[data-cart-summary]').forEach(function (n) {
      n.value = cart.map(function (l) { return l.qty + ' x ' + l.name + ' (' + money(l.price) + ')'; }).join('\n');
    });
    var removeLabel = document.querySelector('[data-remove-label]');
    document.querySelectorAll('[data-cart-lines]').forEach(function (list) {
      list.textContent = '';
      cart.forEach(function (line, index) {
        var li = el('li');
        li.appendChild(el('span', '', line.qty + ' × ' + line.name));
        li.appendChild(el('span', '', money(line.qty * line.price)));
        var remove = el('button', '', removeLabel ? removeLabel.textContent : '×');
        remove.type = 'button';
        remove.addEventListener('click', function () { var c = readCart(); c.splice(index, 1); writeCart(c); });
        li.appendChild(remove);
        list.appendChild(li);
      });
    });
    document.querySelectorAll('[data-cart-empty]').forEach(function (n) { n.hidden = cart.length > 0; });
  }
  // The order was accepted by the shop: empty the cart.
  if (state === 'sent' && document.querySelector('[data-cart]')) {
    try { localStorage.removeItem(store); } catch (e) {}
  }
  bindCart();
  renderCart();
  document.querySelectorAll('form[data-form]').forEach(function (form) {
    if (!form.querySelector('[data-cart-summary]')) return;
    form.addEventListener('submit', function (event) {
      if (!readCart().length) event.preventDefault();
    });
  });
})();
